// Neon Auth 0.6 injects set-auth-jwt into getSession().data.session.token.
// Its /token client path shares the session cache and may return a session object.
async function tunnelSessionToken(auth,onExpired){
 const {data,error}=await auth.getSession();
 if(error){
  if(error.status===401){onExpired();throw new Error('A sessão terminou. Entra novamente com Google.');}
  throw new Error('Não foi possível verificar a sessão. Tenta novamente.');
 }
 const token=data?.session?.token;
 if(!data?.user||typeof token!=='string'||!/^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(token)){
  onExpired();throw new Error('A sessão terminou. Entra novamente com Google.');
 }
 return {data:{token},error:null};
}

const technicalAuth=Lf('https://ep-icy-cloud-ba8486l7.neonauth.c-8.eu-central-1.aws.neon.tech/tunnel/auth');
const techEl=id=>document.getElementById(id);
let technicalAuthorized=false;
function techStatus(text){techEl('status').textContent=text;}
function technicalExpired(){
 technicalAuthorized=false;
 techEl('live-log').replaceChildren();techEl('live-threads').replaceChildren();
 techEl('live-title').textContent='';techEl('live-status').textContent='';
 liveConversation=null;liveAfter='0';
 techEl('technical-workspace').hidden=true;techEl('login').hidden=false;
 techEl('google').disabled=false;techEl('logout').hidden=true;
}
async function verifyTechnical(){
 try{
  const {data,error}=await technicalAuth.getSession();
  if(error)throw Error('Não foi possível verificar a sessão.');
  if(!data?.user){technicalExpired();techStatus('Entra com a tua conta Google autorizada.');return;}
  const token=await tunnelSessionToken(technicalAuth,technicalExpired);
  const r=await fetch('/api/technical',{headers:{Authorization:'Bearer '+token.data.token}}),result=await r.json();
  if(!r.ok){technicalExpired();throw Error(result.error||'Não foi possível verificar o acesso técnico.');}
  technicalAuthorized=true;techEl('login').hidden=true;techEl('retry').hidden=true;
  techEl('logout').hidden=false;techEl('technical-workspace').hidden=false;techStatus('');
  await loadLiveThreads();
 }catch(e){techStatus(e.message);techEl('retry').hidden=false;}
}
techEl('google').onclick=async()=>{techEl('google').disabled=true;try{const r=await technicalAuth.signIn.social({provider:'google',callbackURL:location.origin+'/tecnico.html'});if(r.error)throw Error(r.error.message);}catch(e){techStatus(e.message);techEl('google').disabled=false;}};
techEl('logout').onclick=async()=>{const result=await technicalAuth.signOut();if(result.error){techStatus('Não foi possível sair. Tenta novamente.');return;}technicalExpired();location.reload();};
techEl('retry').onclick=verifyTechnical;

let liveConversation=null,liveAfter='0',liveBusy=false;
const liveEl=id=>document.getElementById(id);
async function liveRequest(params={}){
 const token=await tunnelSessionToken(technicalAuth,technicalExpired);
 const response=await fetch('/api/chat?'+new URLSearchParams({view:'technical',...params}),{headers:{Authorization:'Bearer '+token.data.token}});
 const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível carregar as conversas.');return result;
}
async function loadLiveThreads(){
 if(!technicalAuthorized||liveBusy||liveConversation)return;liveBusy=true;
 try{const data=await liveRequest();if(!technicalAuthorized)return;liveEl('live-threads').replaceChildren();for(const item of data.conversations){const button=document.createElement('button');button.textContent=item.customer_name+' · '+item.barber_name+(item.awaiting?' · Por responder':'');button.onclick=()=>openLiveThread(item);liveEl('live-threads').append(button);}liveEl('live-status').textContent=data.conversations.length?'Conversas reais guardadas.':'Ainda não há conversas reais.';}
 catch(error){liveEl('live-status').textContent='Não foi possível atualizar. '+error.message;}finally{liveBusy=false;}
}
function openLiveThread(item){liveConversation=item.id;liveAfter='0';liveEl('live-log').replaceChildren();liveEl('live-title').textContent=item.customer_name+' · '+item.barber_name;liveEl('live-threads').hidden=true;liveEl('live-back').hidden=false;loadLiveMessages();}
async function loadLiveMessages(){
 if(!technicalAuthorized||!liveConversation||liveBusy)return;liveBusy=true;const id=liveConversation;
 try{const data=await liveRequest({conversation:id,after:liveAfter});if(!technicalAuthorized||id!==liveConversation)return;for(const message of data.messages){const article=document.createElement('article'),sender=document.createElement('strong'),body=document.createElement('p'),time=document.createElement('time');sender.textContent=message.sender_name;body.textContent=message.body;time.dateTime=message.created_at;time.textContent=new Date(message.created_at).toLocaleString('pt-PT');article.append(sender,body,time);liveEl('live-log').append(article);liveAfter=String(message.id);}liveEl('live-status').textContent=liveAfter==='0'?'Conversa aberta, ainda sem mensagens.':'Mensagens atualizadas.';liveEl('live-more').hidden=data.messages.length<100;}
 catch(error){liveEl('live-status').textContent='Não foi possível atualizar. '+error.message;}finally{liveBusy=false;}
}
liveEl('live-refresh').onclick=()=>liveConversation?loadLiveMessages():loadLiveThreads();
liveEl('live-more').onclick=loadLiveMessages;
liveEl('live-back').onclick=()=>{liveConversation=null;liveEl('live-log').replaceChildren();liveEl('live-title').textContent='';liveEl('live-threads').hidden=false;liveEl('live-back').hidden=true;liveEl('live-more').hidden=true;loadLiveThreads();};
setInterval(()=>{if(technicalAuthorized&&!document.hidden)(liveConversation?loadLiveMessages:loadLiveThreads)();},6000);

verifyTechnical();
